func withStableIdentity(id, name string, scenario Scenario) Scenario {
	scenario.ID = id
	scenario.Name = name
	return scenario
}

func withStartingSettlers(count int, scenario Scenario) Scenario {
	scenario.Budgets.StartingSettlers = count
	return scenario
}

